Sys.setenv(LIHTC_REFRESH_OUTPUT='./output/research_extensions/28_paper_state_guarded_refresh')
source(file.path(Sys.getenv('LIHTC_REFRESH_OUTPUT'),'engine.R'))
library(data.table)
base<-path('data_raw/LODES/primary_wac_2010_2019');dest<-file.path(OUT,'primary_wac')
m<-read_csv(file.path(base,'download_manifest.csv'),show_col_types=FALSE);stopifnot(nrow(m)==510); m<-m%>%filter(status%in%c('success','cached'))
r<-map2_dfr(m$state,m$year,~read_parquet(file.path(base,'tract_chunks',paste0('wac_JT01_',.x,'_',.y,'.parquet'))))%>%transmute(tract_id=as.numeric(w_tract),year=as.integer(year),primary_wac_total=C000)
stopifnot(!anyDuplicated(r[c('tract_id','year')]))
write_parquet(r,file.path(dest,'primary_wac_tract_panel.parquet'))
p<-left_join(p,r,by=c('tract_id','year'),relationship='one-to-one')%>%mutate(log_primary_wac=log(pmax(primary_wac_total,1)))
write_csv(p%>%group_by(year)%>%summarise(rows=n(),missing_primary=sum(is.na(primary_wac_total)),primary_exceeds_all=sum(primary_wac_total>wac_total,na.rm=TRUE)),file.path(dest,'coverage.csv'))
stopifnot(all(p$primary_wac_total<=p$wac_total,na.rm=TRUE))
write_csv(p%>%filter(is.finite(wac_total),is.na(primary_wac_total))%>%select(tract_id,year,wac_total),file.path(dest,'missing_primary_on_all_job_rows.csv'))
# Shared outcome-complete rows and unchanged matching assignments.
run(p,pairs,c('wac_total','primary_wac_total','log_wac','log_primary_wac'),c('pooled','lower_income','higher_income'),'primary_wac/comparison')
a<-read_csv(file.path(dest,'comparison/att.csv'),show_col_types=FALSE)
old<-read_csv(file.path(OUT,'all_att.csv'),show_col_types=FALSE)%>%filter(analysis=='main/wac_total')%>%select(group,specification,outcome,original_estimate=estimate,original_se=std_error,original_n=observations)
z<-inner_join(a,old,by=c('group','specification','outcome'))%>%mutate(estimate_difference=estimate-original_estimate,se_difference=std_error-original_se,n_difference=observations-original_n)
write_csv(z,file.path(dest,'all_job_reconciliation.csv'))
writeLines(if(all(abs(z$estimate_difference)<1e-8)&all(z$n_difference==0))'PASS: identical all-job estimates and observations.' else 'Common-sample comparison differs; inspect reconciliation before plotting.',file.path(dest,'VALIDATION.txt'))
